package com.crms.controller;import com.crms.entity.PlacementDrive;import com.crms.repository.PlacementDriveRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/drives") public class DriveController{private final PlacementDriveRepository drives;public DriveController(PlacementDriveRepository d){drives=d;}@GetMapping public List<PlacementDrive> all(){return drives.findAll();}@GetMapping("/{id}")public PlacementDrive get(@PathVariable Long id){return drives.findById(id).orElseThrow();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','PLACEMENT_OFFICER')")public PlacementDrive create(@RequestBody PlacementDrive d){return drives.save(d);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','PLACEMENT_OFFICER')")public PlacementDrive update(@PathVariable Long id,@RequestBody PlacementDrive in){var d=get(id);d.setName(in.getName());d.setDescription(in.getDescription());d.setStartDate(in.getStartDate());d.setEndDate(in.getEndDate());d.setActive(in.isActive());return drives.save(d);}@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','PLACEMENT_OFFICER')")public void delete(@PathVariable Long id){drives.deleteById(id);}}
